SINA_SMART["histo1-nervous"] = {"lecture":"histo1-nervous","title":"Nervous tissue","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"histo1-nervous:e1","text":"Dendrites to the soma; single axon away from it.","topic":"Nervous tissue and the neuron","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-nervous:e2","text":"Nissl bodies = RER + ribosomes; absent from axon hillock and axon.","topic":"Nervous tissue and the neuron","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-nervous:e3","text":"Multipolar (most, motor), bipolar (retina, olfaction), pseudounipolar (dorsal root ganglion).","topic":"Types of neurons","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-nervous:e4","text":"Myelin: Schwann cell = 1 internode (PNS); oligodendrocyte = many axons (CNS).","topic":"Myelin and nerve fibres","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-nervous:e5","text":"Nodes of Ranvier → saltatory conduction.","topic":"Myelin and nerve fibres","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-nervous:e6","text":"Endoneurium (axon), perineurium (fascicle, barrier), epineurium (nerve).","topic":"Myelin and nerve fibres","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-nervous:e0","text":"Neurons + neuroglia, from neuroectoderm (microglia from monocytes).","topic":"Neuroglia and grey vs white matter","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-nervous:e7","text":"Blood-brain barrier: endothelium + basement membrane + astrocyte foot processes.","topic":"Neuroglia and grey vs white matter","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-nervous:e8","text":"Microglia phagocytose; ependymal cells line ventricles; satellite cells in ganglia.","topic":"Neuroglia and grey vs white matter","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-nervous:e9","text":"Grey matter: cell bodies; white matter: myelinated fibres.","topic":"Neuroglia and grey vs white matter","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"14f63iz":"a","1q2kdhv":"a","uhnvkr":"a","ionu6e":"a","1xdlnh3":"a","wpfxi1":"a","1q1du84":"a","osg4i0":"a","1fxbnq4":"a","1b6wcxu":"a","62tcbr":"a","ez2kad":"a","1hfd8ex":"a","u29n9m":"a","aip9o8":"x"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"histo1-nervous:e1":{"s":0,"u":["Dendrites to the soma; single axon away from it.","The neuron is the structural and functional unit: a cell body (soma, perikaryon) with processes: dendrites (usually many, thick, branching, carrying impulses to the soma) and a single axon (thinner, fewer branches, carrying impulses away ).","Nissl bodies are basophilic clumps of rough ER and free ribosomes in the soma and dendrite bases, absent in the axon hillock and axon."],"dp":[]},"histo1-nervous:e2":{"s":0,"u":["Nissl bodies = RER + ribosomes; absent from axon hillock and axon.","Nissl bodies are basophilic clumps of rough ER and free ribosomes in the soma and dendrite bases, absent in the axon hillock and axon."],"dp":[]},"histo1-nervous:e3":{"s":1,"u":["Multipolar (most, motor), bipolar (retina, olfaction), pseudounipolar (dorsal root ganglion).","By the number of processes: multipolar (many dendrites and one axon: most neurons, about 99%, e.g. motor neurons), bipolar (one dendrite and one axon: retina, olfactory epithelium, inner ear) and pseudounipolar (one process that splits in two: sensory neurons of the dorsal root ganglia)."],"dp":[]},"histo1-nervous:e4":{"s":2,"u":["Myelin: Schwann cell = 1 internode (PNS); oligodendrocyte = many axons (CNS).","A Schwann cell myelinates a single internode of one axon (internodes up to 1.5 mm), whereas one oligodendrocyte can myelinate up to about 50 axons .","Myelin is a lipid-rich (phospholipids, glycolipids, cholesterol) insulating sheath made by oligodendrocytes in the CNS and Schwann cells in the PNS ."],"dp":[{"h":"Why peripheral nerves can regrow and central tracts cannot","t":"When a peripheral axon is cut, the distal part degenerates, but the Schwann cells survive, clear the debris and line up inside the endoneurial tube as a guiding column, secreting growth factors. The axon can regrow along it at about 1 mm a day. In the CNS, oligodendrocytes each serve many axons and do not form such tubes; their myelin debris and the glial scar made by astrocytes actively inhibit growth. That difference in glial behaviour is why a cut nerve in the arm can recover while a spinal cord injury usually does not. Source: the lecture's Schwann cells, oligodendrocytes and nerve wrappings."}]},"histo1-nervous:e5":{"s":2,"u":["Nodes of Ranvier → saltatory conduction.","Gaps between segments are the nodes of Ranvier , where the impulse jumps: saltatory conduction , up to about 150 times faster than in unmyelinated fibres."],"dp":[]},"histo1-nervous:e6":{"s":2,"u":["Endoneurium (axon), perineurium (fascicle, barrier), epineurium (nerve).","A peripheral nerve contains hundreds to hundreds of thousands of fibres in fascicles: endoneurium around each axon, perineurium around each fascicle (fibroblast-derived cells with tight junctions forming a barrier), epineurium around the whole nerve."],"dp":[]},"histo1-nervous:e0":{"s":3,"u":["Neurons + neuroglia, from neuroectoderm (microglia from monocytes).","Microglia : phagocytes of the CNS (from monocytes)."],"dp":[]},"histo1-nervous:e7":{"s":3,"u":["Blood-brain barrier: endothelium + basement membrane + astrocyte foot processes.","Astrocytes : many processes; support, nutrition, repair; their foot processes, with endothelium and basement membrane, form the blood-brain barrier ."],"dp":[]},"histo1-nervous:e8":{"s":3,"u":["Microglia phagocytose; ependymal cells line ventricles; satellite cells in ganglia.","Ependymal cells : line the ventricles and central canal.","Satellite cells : surround neuron cell bodies in ganglia."],"dp":[]},"histo1-nervous:e9":{"s":3,"u":["Grey matter: cell bodies; white matter: myelinated fibres.","In the CNS, grey matter contains neuron cell bodies, neuroglia and unmyelinated dendrites; white matter contains no cell bodies, mainly myelinated fibres .","Satellite cells : surround neuron cell bodies in ganglia."],"dp":[]}},"meta":{"14f63iz":{"a":"recall","vg":"histo1-nervous:e2/recall/1"},"1q2kdhv":{"a":"recall","vg":"histo1-nervous:e2/recall/2"},"uhnvkr":{"a":"recall","vg":"histo1-nervous:e1/recall/1"},"ionu6e":{"a":"recall","vg":"histo1-nervous:e3/recall/1"},"1xdlnh3":{"a":"recall","vg":"histo1-nervous:e3/recall/1"},"wpfxi1":{"a":"recall","vg":"histo1-nervous:e3/recall/2"},"1q1du84":{"a":"recall","vg":"histo1-nervous:e4/recall/1"},"osg4i0":{"a":"recall","vg":"histo1-nervous:e4/recall/2"},"1fxbnq4":{"a":"relationship","vg":"histo1-nervous:e5/relationship/1"},"1b6wcxu":{"a":"recall","vg":"histo1-nervous:e6/recall/1"},"62tcbr":{"a":"recall","vg":"histo1-nervous:e7/recall/1"},"ez2kad":{"a":"recall","vg":"histo1-nervous:e0/recall/1"},"1hfd8ex":{"a":"recall","vg":"histo1-nervous:e8/recall/1"},"u29n9m":{"a":"recall","vg":"histo1-nervous:e9/recall/1"}},"explRev":"a09793d0484c"};
